INSERT INTO plan_case (plan_id, case_id, result, exec_type, plan_date)
SELECT #{planId}, id, '未执行', '手动执行', #{planDate}
FROM test_case
WHERE project_id = #{projectId}

mapper.select:
SELECT COUNT(1)
FROM plan_case
WHERE plan_id = #{planId} AND result = #{result}

mapper.update:
UPDATE plan_case
SET result = CASE WHEN RAND() < 0.8 THEN '成功' ELSE '失败' END,
    exec_type = #{execType},
    execute_time = #{executeTime}
WHERE plan_id = #{planId}

UPDATE plan_case
SET execute_time = #{executeTime}
WHERE plan_id = #{planId} AND result IN ('成功', '失败')

UPDATE plan_case
SET plan_date = #{planDate}
WHERE plan_id = #{planId}
